// Builds the 1:1 welcome email. Spanish is the default when preferredLanguage
// is UNKNOWN -- Ivan's call, Aug 8 2026. EN/PT are used only when Twenty
// actually says so, so a known English athlete never gets a Spanish email.

// >>>>>>>>>>>>>>>>  SET THIS ONCE  <<<<<<<<<<<<<<<<
const FORM_URL = 'PEGAR_AQUI_EL_LINK_DEL_FORMULARIO';
// >>>>>>>>>>>>>>>>>>>>>>><<<<<<<<<<<<<<<<<<<<<<<<<<

const LOGIN_URL = 'https://triaperformance.com/members/login';

// Fail loudly rather than emailing a broken link to a paying athlete.
if (FORM_URL.startsWith('PEGAR_AQUI')) {
  throw new Error('Build Welcome Email: FORM_URL no esta configurado. Poner el link real del formulario antes de activar.');
}

const T = {
  SPANISH: (n, tok) => ({
    subject: `${n}, arrancamos con tu entrenamiento`,
    body:
`Hola ${n},

Gracias por confiar en mi para tu entrenamiento. Ya estas dentro del equipo.

Para armarte el plan necesito conocerte primero. Son dos pasos.

1) Completa este formulario
${FORM_URL}
Historial, carreras recientes, como vienes entrenando y tus preferencias.
Tomate el tiempo de responderlo bien: de ahi sale todo lo demas.

2) Hablamos por WhatsApp
Dentro de las 24 horas de que completes el formulario nos ponemos de acuerdo
sobre tu semana real: que dias entrenas cada deporte, cuando tienes piscina,
que dia prefieres descansar y cuanto tiempo tienes cada manana o cada tarde.
Con eso te dejo cargados tus primeros dias de entrenamiento.

Tu acceso al Area de Miembros
Link: ${LOGIN_URL}
Contrasena: ${tok}
Ahi estan las calculadoras, guias y herramientas. Guarda este correo: es tu
unica copia de la contrasena.

Cualquier duda me escribes.

Gracias y nos hablamos,
Ivan Koch
Triaperformance`
  }),

  ENGLISH: (n, tok) => ({
    subject: `${n}, let's get your training started`,
    body:
`Hi ${n},

Thanks for trusting me with your training. You're on the team.

Before I can build your plan I need to know you. Two steps.

1) Fill in this form
${FORM_URL}
Background, recent races, how you've been training, and your preferences.
Take your time with it: everything else is built from these answers.

2) We talk on WhatsApp
Within 24 hours of you submitting the form we'll go through your real week:
which days you train each sport, when you have pool access, which day you
prefer to rest, and how much time you have each morning or evening.
Then I load your first days of training.

Your Members Area access
Link: ${LOGIN_URL}
Password: ${tok}
That's where the calculators, guides and tools live. Keep this email: it's
your only copy of the password.

Any questions, just write to me.

Thanks, and talk soon,
Ivan Koch
Triaperformance`
  }),

  PORTUGUESE: (n, tok) => ({
    subject: `${n}, vamos comecar o seu treino`,
    body:
`Ola ${n},

Obrigado por confiar em mim para o seu treino. Voce ja esta no time.

Para montar o seu plano preciso te conhecer primeiro. Sao dois passos.

1) Preencha este formulario
${FORM_URL}
Historico, provas recentes, como voce vem treinando e suas preferencias.
Responda com calma: e daqui que sai todo o resto.

2) Conversamos pelo WhatsApp
Ate 24 horas depois de voce enviar o formulario combinamos a sua semana real:
quais dias voce treina cada esporte, quando tem piscina, qual dia prefere
descansar e quanto tempo tem cada manha ou cada tarde.
Com isso eu carrego os seus primeiros dias de treino.

Seu acesso a Area de Membros
Link: ${LOGIN_URL}
Senha: ${tok}
E la que estao as calculadoras, guias e ferramentas. Guarde este email: e a
sua unica copia da senha.

Qualquer duvida e so me escrever.

Obrigado, ate ja,
Ivan Koch
Triaperformance`
  }),
};

return $input.all().map(() => {
  const norm = $('Normalize Coaching Athlete').item.json;
  const ups  = $('Coaching Athlete Upserted').item.json;
  const tok  = $('Generate Coaching Token').item.json.member_token;

  const lang = T[ups.preferredLanguage] ? ups.preferredLanguage : 'SPANISH';
  const first = (norm.firstname || '').split(/\s+/)[0] || norm.full_name || '';

  const built = T[lang](first, tok);

  return { json: {
    to: norm.email,
    langUsed: lang,
    langWasKnown: Boolean(T[ups.preferredLanguage]),
    subject: built.subject,
    body: built.body,
  }};
});
